import type { Metadata } from "next";
const product = { name: "Sac de voyage", description: "Sac cabine robuste", slug: "sac-voyage" };
export const metadata: Metadata = {
  title: `${product.name} | L’ecomax`,
  description: product.description,
  alternates: { canonical: `/produit/${product.slug}` },
  openGraph: { title: product.name, description: product.description },
};

exercise.solution:
Pour SEO technique et métadonnées, la solution maintient une seule autorité et applique précisément « générer les métadonnées depuis la même source produit validée que le rendu, avec une URL absolue stable en production ». Elle rend toutes les fiches partagent les métadonnées du layout et les moteurs ne distinguent plus les produits reproductible puis contrôlé, et elle n’est acceptée que lorsque le HTML construit contient un title distinct, une description utile, la canonique attendue et des données Open Graph identiques au contenu.
